{"result":"import React, {useEffect, useState} from "react";
import {Link, useHistory} from "react-router-dom";
import {connect, useDispatch, useSelector} from "react-redux";
import styled, {withTheme} from "styled-components";
import {darken} from "polished";

import {
    AppBar as MuiAppBar,
    ButtonBase,
    Grid,
    Hidden,
    IconButton as MuiIconButton,
    InputBase,
    Menu,
    MenuItem,
    Toolbar,
} from "@material-ui/core";

import {ArrowDropDown, Menu as MenuIcon} from "@material-ui/icons";

import {Home, Search as SearchIcon} from "react-feather";
import {setDsearchSignOut} from "../redux/actions/dsearchActions";

import {SET_DSEARCH_AUTH_USER} from "../redux/constants";
import {setClusterList, setClusterServerCheck} from "../redux/actions/clusterActions";
import Snackbar from "@material-ui/core/Snackbar";
import MuiAlert from "@material-ui/lab/Alert";
import "../ga";

const AppBar = styled(MuiAppBar)`
  background: ${props => props.theme.header.background};
  color: ${props => props.theme.header.color};
  box-shadow: ${props => props.theme.shadows[1]};
`;

const IconButton = styled(MuiIconButton)`
  svg {
    width: 22px;
    height: 22px;
  }
`;

const Search = styled.div`
  border-radius: 2px;
  background-color: ${props => props.theme.header.background};
  display: none;
  position: relative;
  width: 100%;

  &:hover {
    background-color: ${props => darken(0.05, props.theme.header.background)};
  }

  ${props => props.theme.breakpoints.up("md")} {
    display: block;
  }
`;

const SearchIconWrapper = styled.div`
  width: 50px;
  height: 100%;
  position: absolute;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;

  svg {
    width: 22px;
    height: 22px;
  }
`;

const Input = styled(InputBase)`
  color: inherit;
  width: 100%;

  > input {
    color: ${props => props.theme.header.search.color};
    padding-top: ${props => props.theme.spacing(2.5)}px;
    padding-right: ${props => props.theme.spacing(2.5)}px;
    padding-bottom: ${props => props.theme.spacing(2.5)}px;
    padding-left: ${props => props.theme.spacing(12)}px;
  }
`;

const Button = styled(ButtonBase)`
  color: ${props => props.theme.header.search.color};
  padding-left: ${props => props.theme.spacing(2)}px;
  padding-right: ${props => props.theme.spacing(2)}px;
`


const deleteCookie = function(name) {
    const date = new Date();
    document.cookie = name + "= " + "; expires=" + date.toUTCString() + "; path=/";
}

function ClusterMenu() {
    const dispatch = useDispatch()
    const authUser = useSelector(store => store.dsearchReducers)['authUser']
    const clusterStore = useSelector(store => store.clusterReducers)
    const [clusterListMenu, setClusterListMenu] = useState(null);

    useEffect(() => {
        dispatch(setClusterList())
    }, []) // eslint-disable-line react-hooks/exhaustive-deps

    function toggleMenu(event) {
        setClusterListMenu(event.currentTarget)
    }
    function closeMenu() {
        setClusterListMenu(null)
    }

    function changeCluster(clusterId) {
        closeMenu()
        if (authUser['cluster']['id'] === clusterId) {
            return false
        }
        // eslint-disable-next-line no-restricted-globals
        location.href = `/${clusterId }/dashboard`
    }

    const open = Boolean(clusterListMenu);
    return (
        <React.Fragment>
            <Button aria-owns={open ? "menu-appbar" : undefined}
                    aria-haspopup="true"
                    onClick={toggleMenu}
                    variant={"outlined"}
            >
                {authUser['cluster']['name']}
                <ArrowDropDown/>
            </Button>
            <Menu
                anchorEl={clusterListMenu}
                open={open}
                onClose={closeMenu}
            >
                {
                    (clusterStore['clusterList']||[]).map(cluster => {
                        return (
                            <MenuItem key={cluster['cluster']['id']}
                                      onClick={() => changeCluster(cluster['cluster']['id'])}
                            >
                                {cluster['cluster']['name']}
                            </MenuItem>
                        )
                    })
                }
            </Menu>
        </React.Fragment>
    )
}

function UserMenu({ signOutClose = false }) {
    const dispatch = useDispatch()
    const authUser = useSelector(store => store.dsearchReducers.authUser)
    const [anchorMenu, setAnchorMenu] = useState(null)
    const open = Boolean(anchorMenu);

    function toggleMenu(event) {
        setAnchorMenu(event.currentTarget)
    }

    function closeMenu() {
        setAnchorMenu(null)
    }

    function signOut() {
        deleteCookie(SET_DSEARCH_AUTH_USER)
        localStorage.removeItem(SET_DSEARCH_AUTH_USER)
        dispatch(setDsearchSignOut()).then(response => {
            if (signOutClose) {

                try {
                    // eslint-disable-next-line no-restricted-globals
                    opener.sessionStorage.removeItem(SET_DSEARCH_AUTH_USER)
                    // eslint-disable-next-line no-restricted-globals
                    opener.localStorage.removeItem(SET_DSEARCH_AUTH_USER)
                } catch(error) {}

                try {
                    const date = new Date();
                    // eslint-disable-next-line no-restricted-globals
                    opener.document.cookie = SET_DSEARCH_AUTH_USER + "= " + "; expires=" + date.toUTCString() + "; path=/";
                } catch(error) {}

                try {
                    // eslint-disable-next-line no-restricted-globals
                    opener.location.href="/"
                } catch(error) {
                    // ignore
                }
                window.close()
            }
        }).catch(error => {
            console.error('error', error)
            if (signOutClose) {

                try {
                    // eslint-disable-next-line no-restricted-globals
                    opener.sessionStorage.removeItem(SET_DSEARCH_AUTH_USER)
                    // eslint-disable-next-line no-restricted-globals
                    opener.localStorage.removeItem(SET_DSEARCH_AUTH_USER)
                } catch(error) {}

                try {
                    const date = new Date();
                    // eslint-disable-next-line no-restricted-globals
                    opener.document.cookie = SET_DSEARCH_AUTH_USER + "= " + "; expires=" + date.toUTCString() + "; path=/";
                } catch(error) {}


                try {
                    // eslint-disable-next-line no-restricted-globals
                    opener.location.href="/"
                } catch(error) {
                    // ignore
                }
                window.close()
            }
        })
    }

    return (
        <React.Fragment>
            <Button aria-owns={open ? "menu-appbar" : undefined}
                    aria-haspopup="true"
                    onClick={toggleMenu}
                    variant={"outlined"}
            >
                {/*{(authUser['userManagement'] || {})['username']}*/}
                {(authUser['user'] || {})['email']}
                <ArrowDropDown/>
            </Button>

            <Menu
                id="menu-appbar"
                anchorEl={anchorMenu}
                open={open}
                onClose={closeMenu}
            >
                <MenuItem
                    component={Link}
                    to={"/my"}
                >
                    정보수정
                </MenuItem>
                <MenuItem
                    component={Link}
                    onClick={signOut}
                    to={"/"}
                >
                    로그아웃
                </MenuItem>
            </Menu>
        </React.Fragment>
    );
}


const MainHeader = ({theme, onDrawerToggle}) => (
    <React.Fragment>
        <AppBar position="sticky" elevation={0}>
            <Toolbar>
                <Grid container alignItems="center">
                    <Hidden mdUp>
                        <Grid item>
                            <IconButton
                                color="inherit"
                                aria-label="Open drawer"
                                onClick={onDrawerToggle}
                            >
                                <MenuIcon/>
                            </IconButton>
                        </Grid>
                    </Hidden>
                    <Grid item/>
                    <Grid item xs/>

                    <Grid item>
                        {/*<ClusterMenu theme={theme}/>*/}
                        <UserMenu theme={theme}/>
                    </Grid>
                </Grid>
            </Toolbar>
        </AppBar>
    </React.Fragment>)



const DashBoardHeader = ({theme, onDrawerToggle}) => {
    const references = useSelector(store => ({...store.referenceSearchReducers}))

    const [keyword, setKeyword] = useState(references.keyword)
    // eslint-disable-next-line no-restricted-globals
    const qs = new URLSearchParams(location.search)
    const history = useHistory()

    function handleSearch() {
        let search = "https://search.danawa.com/dsearch.php?k1=" + encodeURIComponent(keyword);

        window.open(search, '_blank', "menubar=no,addressbar=no,statusbar=no")
    }

    function handleKeyEvent(event, val) {
        if (event.keyCode === 13) {
            handleSearch()
        }
    }

    function handleKeyword(event, val) {
        let value = event.target.value;
        if(value === 0){
            setKeyword(val);
        }else{
            setKeyword(value);
        }

        if (event.keyCode === 13) {
            handleSearch()
        }
    }

    if (qs.get("keyword") !== null && qs.get("keyword") !== keyword) {
        setKeyword(qs.get("keyword"))
        handleSearch()
    }
    return (
        <React.Fragment>
            <AppBar position="sticky" elevation={0}>
                <Toolbar>
                    <Grid container alignItems="center">
                        <Hidden mdUp>
                            <Grid item>
                                <IconButton
                                    color="inherit"
                                    aria-label="Open drawer"
                                    onClick={onDrawerToggle}
                                >
                                    <MenuIcon/>
                                </IconButton>
                            </Grid>
                        </Hidden>

                        <Grid item xs>

                            <Search>
                                <SearchIconWrapper>
                                    <SearchIcon/>
                                </SearchIconWrapper>

                                <div>
                                    <Input
                                        style={{ width: "100%" }}
                                        placeholder="다나와 통합 검색 (Enter 입력)"
                                        value={keyword}
                                        onChange={handleKeyword}
                                        onKeyUp={handleKeyEvent}
                                    />
                                </div>
                            </Search>
                        </Grid>

                        <Grid item xs={1}/>

                        <Grid item>
                            <IconButton color="inherit"
                                        onClick={() => {
                                            try {
                                                // eslint-disable-next-line no-restricted-globals
                                                if (opener.document === document) {
                                                    history.push("/cluster")
                                                    return
                                                }
                                                const link = document.createElement('a');
                                                link.href = "/cluster"
                                                // eslint-disable-next-line no-restricted-globals
                                                opener.document.body.appendChild(link);
                                                link.click()
                                                window.close()
                                            } catch (error) {
                                                history.push("/cluster")
                                            }
                                        } }>
                                <Home/>
                            </IconButton>
                            <ClusterMenu theme={theme}/>
                            <UserMenu theme={theme} signOutClose={true}/>
                        </Grid>
                    </Grid>
                </Toolbar>
            </AppBar>
        </React.Fragment>
    )
}

let eventCode = null
const Header = ({theme, layout, onDrawerToggle, serverCheck}) => {
    const dispatch = useDispatch()

    useEffect(() => {
        if (layout !== "main") {
            handleServerCheck()
        }

        return () => {
            if (eventCode) {
                clearTimeout(eventCode)
                eventCode = null
            }
        }
    }, []) // eslint-disable-line react-hooks/exhaustive-deps

    function handleServerCheck() {
        dispatch(setClusterServerCheck())
        if (!eventCode) {
            clearTimeout(eventCode)
            eventCode = null
        }
        eventCode = setTimeout(() => {
            handleServerCheck()
        }, 5 * 60 * 1000)
    }

    return layout === "main" ?
        <MainHeader theme={theme} onDrawerToggle={onDrawerToggle}/>
        :
        (
            <React.Fragment>
                <DashBoardHeader theme={theme} onDrawerToggle={onDrawerToggle}/>
                <Snackbar
                    anchorOrigin={{vertical: 'top', horizontal: 'center'}}
                    open={serverCheck}
                    autoHideDuration={99999999}
                    onClose={() => {}}
                >
                    <MuiAlert elevation={6} variant="filled" severity="warning">
                        클러스터 점검 중입니다.
                    </MuiAlert>
                </Snackbar>
            </React.Fragment>
        )
}

export default connect(store => ({
    serverCheck: store.clusterReducers.serverCheck
}))(withTheme(Header));"}

