//     background-color: ${props => props.theme.sidebar.footer.online.background};
//     border: 1.5px solid ${props => props.theme.palette.common.white};
//     height: 12px;
//     width: 12px;
//     border-radius: 50%;
//   }
// `;

function SidebarCategory({
                             name,
                             icon,
                             classes,
                             isOpen,
                             isCollapsable,
                             badge,
                             ...rest
                         }) {
    let flag = false;
    if(name === '키바나로 이동') flag = true;
    return (
        <Category {...rest}>
            {icon}
            <CategoryText>{name}</CategoryText>
            {isCollapsable ? (
                isOpen ? (
                    <CategoryIconMore/>
                ) : (
                    <CategoryIconLess/>
                )
            ) : null}
            {badge ? <CategoryBadge label={badge}/> : ""}
            {flag ? <Launch /> : <></>}
        </Category>
    );
}

function SidebarLink({name, to, badge, icon2}) {

    return (
        <Link
            button
            dense
            component={NavLink}
            exact
            to={to}
            activeClassName="active"
        >
            <LinkText>{name}</LinkText>
            {badge ? <LinkBadge label={badge}/> : ""}
        </Link>
    );
}

function Sidebar(props) {
    const [active, setActive] = useState({})

    useEffect(() => {
        /* Open collapse element that matches current url */
        const pathName = props.location.pathname;
        const {layout} = props;
        let routes = [];
        if (layout === 'dashboard') {
            routes = dashboardRoutes
        } else {
            routes = introRoutes
        }

        routes.forEach((route, index) => {
            const isActive = pathName.indexOf(route.path) === 0;
            const isOpen = route.open;
            const isHome = route.containsHome && pathName === "/" ? true : false;

            setActive({
                [index]: isActive || isOpen || isHome
            })
            // this.setState(() => ({
            //     [index]: isActive || isOpen || isHome
            // }));
        });
    }, []) // eslint-disable-line react-hooks/exhaustive-deps

    function toggle(index) {
        // Collapse all elements
        Object.keys(active).forEach(
            item =>
                active[index] ||
                setActive({
                    ...active,
                    [item]: false
                })
        );

        // Toggle selected element
        setActive({
            [index]: !active[index]
        })
        // this.setState(state => ({
        //     [index]: !state[index]
        // }));
    }

    const {classes, layout, staticContext, ...other} = props;
    let routes = [];
    if (layout === 'dashboard') {
        routes = dashboardRoutes
    } else {
        routes = introRoutes
    }


    routes = routes.filter(route => route.hidden === undefined || route.hidden === null || route.hidden === false)
    return (
        <Drawer variant="permanent" {...other}>
            <Brand>
                {/*<BrandIcon/>*/}
                <img src={"/static/img/dsearch/danawa_m.png"} alt={"danawa_m.png"} />
                <Box style={{marginLeft: "12px"}}>
                    {title}
                    {/* <BrandChip label="X" /> */}
                </Box>
            </Brand>
            <Scrollbar>
                <List disablePadding>
                    <Items>
                        {routes.map((category, index) => (
                            <React.Fragment key={index}>
                                {category.header ? (
                                    <SidebarSection>{category.header}</SidebarSection>
                                ) : null}

                                {category.children && category.children.filter(c => c.hidden !== true).length > 0 ? (
                                    <React.Fragment key={index}>
                                        <SidebarCategory
                                            isOpen={!active[index]}
                                            isCollapsable={true}
                                            name={category.id}
                                            icon={category.icon}
                                            button={true}
                                            onClick={() => toggle(index)}
                                        />

                                        <Collapse
                                            in={active[index]}
                                            timeout="auto"
                                            unmountOnExit
                                        >
                                            {category.children.filter(c => c.hidden !== true).map((route, index) => (
                                                <SidebarLink
                                                    key={index}
                                                    name={route.name}
                                                    to={route.path}
                                                    icon={route.icon}
                                                    badge={route.badge}
                                                />
                                            ))}
                                        </Collapse>
                                    </React.Fragment>
                                ) : (
                                    <SidebarCategory
                                        isCollapsable={false}
                                        name={category.id}
                                        to={category.path}
                                        activeClassName="active"
                                        component={NavLink}
                                        icon={category.icon}
                                        // exact
                                        badge={category.badge}
                                    />
                                )}
                            </React.Fragment>
                        ))}
                    </Items>
                </List>
            </Scrollbar>
            {/*<SidebarFooter>*/}
            {/*    <Grid container spacing={2}>*/}
            {/*        <Grid item>*/}
            {/*            <StyledBadge*/}
            {/*                overlap="circle"*/}
            {/*                anchorOrigin={{*/}
            {/*                    vertical: 'bottom',*/}
            {/*                    horizontal: 'right',*/}
            {/*                }}*/}
            {/*                variant="dot"*/}
            {/*            >*/}
            {/*                <Avatar alt="Lucy Lavender" src="/static/img/avatars/avatar-1.jpg"/>*/}
            {/*            </StyledBadge>*/}
            {/*        </Grid>*/}
            {/*        <Grid item>*/}
            {/*            <SidebarFooterText variant="body2">*/}
            {/*                Lucy Lavender*/}
            {/*            </SidebarFooterText>*/}
            {/*            <SidebarFooterSubText variant="caption">*/}
            {/*                UX Designer*/}
            {/*            </SidebarFooterSubText>*/}
            {/*        </Grid>*/}
            {/*    </Grid>*/}
            {/*</SidebarFooter>*/}
        </Drawer>
    )
}

export default withRouter(Sidebar);"}

